48	void SQLLogicTestLogger::PrintExpectedResult(const vector<string> &values, idx_t columns, bool row_wise) {
49		if (row_wise) {
50			for (idx_t r = 0; r < values.size(); r++) {
51				LogFailure("\n" + values[r]);
52			}
53		} else {
54			idx_t c = 0;
55			for (idx_t r = 0; r < values.size(); r++) {
56				if (c != 0) {
57					LogFailure("\t");
58				}
59				LogFailure(values[r]);
60				c++;
61				if (c >= columns) {
62					LogFailure("\n");
63					c = 0;
64				}
65			}
66		}
67		LogFailure("\n");
68	}
