# `[N/M] (P%): <path> took Xs` marks a completed test; the same line without the
# `took` suffix marks a test that has only started.
PROGRESS_DONE_PATTERN = re.compile(r"^\[\d+/\d+\]\s*\(\d+%\):\s*(.+?)\s+took\s+[0-9]+(?:\.[0-9]+)?s\s*$")
PROGRESS_START_PATTERN = re.compile(r"^\[\d+/\d+\]\s*\(\d+%\):\s*(.+?)\s*$")
# Structured failure header emitted by SQLLogicTestLogger: `N. <path>:<line>`.
SUMMARY_HEADER_PATTERN = re.compile(r"^\d+\.\s+(.+):(\d+)\s*$")
TIMEOUT_MESSAGE_PATTERN = re.compile(r"batch timed out after\s+(\S+)\s+seconds")
MISMATCH_VALUE_PATTERN = re.compile(r"^(.*?)\s+<>\s+(.*)$")


def parse_progress_entries(text: str):
    # Returns a list of (test_path, completed) tuples in the order they appeared.
    entries = []
    for line in text.splitlines():
        stripped = line.strip()
        done_match = PROGRESS_DONE_PATTERN.match(stripped)
        if done_match:
            entries.append((done_match.group(1), True))
            continue
        start_match = PROGRESS_START_PATTERN.match(stripped)
        if start_match:
            entries.append((start_match.group(1), False))
    return entries


def identify_timed_out_test(clean_stdout: str, batch: list):
    entries = parse_progress_entries(clean_stdout)
    if not entries:
        # No progress information: assume the last test in the batch hung.
        return batch[-1] if batch else ""
    completed = {path for path, done in entries if done}
    for name in batch:
        if name not in completed:
            return name
    return batch[-1] if batch else ""


def identify_last_started_test(clean_stdout: str, batch: list):
    entries = parse_progress_entries(clean_stdout)
    started = [path for path, done in entries if not done]
    if started:
        return started[-1]
    if entries:
        return entries[-1][0]
    return batch[-1] if batch else ""


def format_timeout_seconds(message: str):
    match = TIMEOUT_MESSAGE_PATTERN.search(message)
    if not match:
        return "0"
    raw = match.group(1)
    try:
        value = float(raw)
    except ValueError:
        return raw
    if value.is_integer():
        return str(int(value))
    return raw


def is_separator_line(line: str):
    stripped = line.strip()
    return len(stripped) >= 3 and set(stripped) == {"="}


def trim_blank_edges(lines: list):
    result = list(lines)
    while result and result[0].strip() == "":
        result.pop(0)
    while result and result[-1].strip() == "":
        result.pop()
    return result


def find_structured_block(clean_stderr: str):
