    lines = clean_stderr.splitlines()
    for idx, line in enumerate(lines):
        header = SUMMARY_HEADER_PATTERN.match(line.strip())
        if header and idx + 1 < len(lines) and is_separator_line(lines[idx + 1]):
            return {
                "test_path": header.group(1),
                "line_number": int(header.group(2)),
                "start": idx,
                "lines": lines,
